package io.github.jesterportfolio.hearth.survival;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.util.concurrent.atomic.AtomicLong;import java.nio.charset.StandardCharsets;
import com.google.gson.*;import com.google.gson.reflect.TypeToken;
import io.github.jesterportfolio.hearth.survival.enchants.*;
class EnchantEngineTest {
    static Map<String,Double> vars(){return Map.of("damage",10.0,"health",3.0,"max_health",20.0,"target_health",5.0,"allies",2.0,"sneaking",1.0,"xp",3.0,"distance",1.0);}
    static Map<String,EnchantDefinition> catalog()throws Exception{var parser=new Gson();var map=new LinkedHashMap<String,EnchantDefinition>();try(var in=EnchantEngineTest.class.getResourceAsStream("/enchants/catalog.json")){var manifest=JsonParser.parseString(new String(in.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();for(var row:manifest.getAsJsonArray("rows")){String id=row.getAsJsonObject().get("id").getAsString();try(var file=EnchantEngineTest.class.getResourceAsStream("/enchants/"+id.split(":")[1]+".yml")){Map<String,Object> raw=parser.fromJson(new String(file.readAllBytes(),StandardCharsets.UTF_8),new TypeToken<Map<String,Object>>(){}.getType());var definition=EnchantDefinition.parse(raw);assertNull(map.put(definition.id(),definition));}}}return Map.copyOf(map);}
    @Test void sourceInventoryHas105UniqueExecutableDefinitions()throws Exception{var catalog=catalog();assertEquals(105,catalog.size());var effects=new HashSet<String>();for(var def:catalog.values()){for(var rule:def.rules()){var engine=new EnchantEngine(()->0,new Random(){public double nextDouble(){return 0;}});var out=engine.plan(UUID.randomUUID(),Map.of(def.id(),1),catalog,rule.trigger(),"minecraft:overworld",vars());assertFalse(out.isEmpty(),def.id()+" "+rule.trigger());out.forEach(x->effects.add(x.effect().type()));for(var effect:rule.effects())for(var expression:effect.expressions().values())assertTrue(Double.isFinite(expression.evaluate(new HashMap<>(vars()){{put("level",1.0);}})));}}assertEquals(31,effects.size());}
    @Test void resourceGenerationAliasesKeepWorldRestrictionsWithoutOpeningUnrelatedWorlds()throws Exception{var original=catalog().get("hearth:ce_haste");var def=new EnchantDefinition(original.id(),original.name(),true,original.maxLevel(),original.equipment(),original.slots(),original.conflicts(),Set.of("hearth_survival:novice"),original.rules(),original.document());var engine=new EnchantEngine(()->0,new Random());assertFalse(engine.plan(UUID.randomUUID(),Map.of(def.id(),1),Map.of(def.id(),def),EnchantDefinition.Trigger.EQUIP,Set.of("hearth_resource:new_generation","hearth_survival:novice","role:novice"),vars()).isEmpty());assertTrue(engine.plan(UUID.randomUUID(),Map.of(def.id(),1),Map.of(def.id(),def),EnchantDefinition.Trigger.EQUIP,Set.of("hearth_survival:wilderness","role:wilderness"),vars()).isEmpty());}
    @Test void formulasRespectMathBooleanPrecedenceAndLimits(){assertEquals(7,Formula.of("1+2*3").evaluate(Map.of()));assertEquals(1,Formula.of("1 || 0 && 0").evaluate(Map.of()));assertEquals(0,Formula.of("(1 || 0) && 0").evaluate(Map.of()));assertEquals(4,Formula.of("clamp(level*2,1,4)").evaluate(Map.of("level",3.0)));assertThrows(IllegalArgumentException.class,()->Formula.of("java.lang.Runtime()"));assertThrows(IllegalArgumentException.class,()->Formula.of("1/0").evaluate(Map.of()));assertThrows(IllegalArgumentException.class,()->Formula.of("(".repeat(60)+"1"+")".repeat(60)));}
    @Test void stickyShotCoversEntityAndBlockImpactsWithOneActivationPoint()throws Exception{var def=catalog().get("hearth:ce_sticky_shot");assertEquals(1,def.rules().size());assertEquals(EnchantDefinition.Trigger.ARROW_IMPACT,def.rules().getFirst().trigger());assertEquals(EnchantDefinition.Target.BLOCK,def.rules().getFirst().effects().getFirst().target());assertEquals("1",def.rules().getFirst().effects().getFirst().arguments().get("radius"));}
    @Test void cooldownIsSharedByStableIdAndNotByItemCopy()throws Exception{var defs=catalog();var def=defs.get("hearth:ce_tamer");var time=new AtomicLong();var engine=new EnchantEngine(time::get,new Random(4));var player=UUID.randomUUID();assertFalse(engine.plan(player,Map.of(def.id(),1),defs,EnchantDefinition.Trigger.ATTACK,"minecraft:overworld",vars()).isEmpty());assertTrue(engine.plan(player,Map.of(def.id(),1),defs,EnchantDefinition.Trigger.ATTACK,"minecraft:overworld",vars()).isEmpty());assertTrue(engine.plan(player,Map.of(def.id(),1),defs,EnchantDefinition.Trigger.DEFEND,"minecraft:overworld",vars()).isEmpty());time.set(120000);assertFalse(engine.plan(player,Map.of(def.id(),1),defs,EnchantDefinition.Trigger.ATTACK,"minecraft:overworld",vars()).isEmpty());}
    @Test void disabledUnknownAndOverLevelNeverRunAndDoNotEraseSavedIds()throws Exception{var all=catalog();var original=all.get("hearth:ce_haste");var d=new EnchantDefinition(original.id(),original.name(),false,original.maxLevel(),original.equipment(),original.slots(),original.conflicts(),original.worlds(),original.rules(),original.document());var engine=new EnchantEngine(()->0,new Random());var saved=new HashMap<>(Map.of(d.id(),2,"hearth:future_id",7));var before=Map.copyOf(saved);assertTrue(engine.plan(UUID.randomUUID(),saved,Map.of(d.id(),d),EnchantDefinition.Trigger.EQUIP,"minecraft:overworld",vars()).isEmpty());assertEquals(before,saved);assertTrue(engine.plan(UUID.randomUUID(),Map.of(original.id(),100),all,EnchantDefinition.Trigger.EQUIP,"minecraft:overworld",vars()).isEmpty());}
    @Test void novicePenaltyScopeIsConfigurableWithoutRewritingLegacyPolicy()throws Exception{var p=new Properties();try(var in=EnchantEngineTest.class.getResourceAsStream("/rpg-policy.properties")){p.load(in);}var policy=io.github.jesterportfolio.hearth.survival.rpg.RpgPolicy.parse(p);assertEquals(Set.of(io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role.NOVICE_RESOURCE),policy.penaltyWorlds());p.remove("penalty-worlds");assertEquals(6,io.github.jesterportfolio.hearth.survival.rpg.RpgPolicy.parse(p).penaltyWorlds().size());}
    @Test void rulesCannotInjectUnknownTriggersOrUnboundedEffectLists(){var p=new HashMap<String,Object>();p.put("version",1);p.put("id","hearth:test");p.put("name","test");p.put("enabled",true);p.put("max-level",1);p.put("equipment",List.of("any"));p.put("slots",List.of("MAIN_HAND"));p.put("rules",List.of(Map.of("trigger","COMMAND_EXECUTE","effects",List.of(Map.of("type","heal")))));assertThrows(IllegalArgumentException.class,()->EnchantDefinition.parse(p));}
    @Test void enchantMarkerExtendsSingleActorNativeTransactionWithoutChangingPeerContract(){var id=UUID.randomUUID();new io.github.jesterportfolio.hearth.survival.economy.NativeTradeJournal.Pending(UUID.randomUUID(),"ENCHANT",List.of(id));assertThrows(IllegalArgumentException.class,()->new io.github.jesterportfolio.hearth.survival.economy.NativeTradeJournal.Pending(UUID.randomUUID(),"ENCHANT",List.of(id,UUID.randomUUID())));}
}
